mapper.select:
SELECT vr.id, vr.member_id AS memberId, m.phone AS memberPhone, vr.template_id AS templateId, ct.name AS couponName, vr.verification_code AS verificationCode, vr.verifier, vr.verification_time AS verificationTime, vr.create_time AS createTime FROM verification_record vr LEFT JOIN member m ON vr.member_id = m.id LEFT JOIN coupon_template ct ON vr.template_id = ct.id WHERE vr.verification_time IS NOT NULL
AND m.phone LIKE CONCAT('%', #{query.phone}, '%')
AND vr.verification_time >= #{query.startTime}
AND vr.verification_time <= #{query.endTime}
ORDER BY vr.verification_time DESC
